using System;
using System.Collections;
using System.IO;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using UnityEngine.TestTools;
using LastRail.Auth;
using LastRail.Battle;
using LastRail.Run;
namespace LastRail.Tests.EditMode {public sealed class BDepartureRuntimeInputTests {
 const string Qa="D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BResultV2Transport-20261006/";
 static JObject Source()=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-result-v2-tcp-20261006.json"))["originalDepartureInput"].DeepClone();
 static BDepartureRuntimeInput Read(JObject p){var b=(JObject)p.DeepClone();b.Remove("packetHash");p["packetHash"]=BDirectAttackInput.Digest(b).Substring(7);return BDepartureRuntimeInput.Read(p.ToString(),(string)p["packetHash"],(string)p["accountId"],(string)p["runId"]);}
 [Test] public void OriginalFiveSelectionsAndSeparateCarsStayImmutableWithoutOccupantAuthority(){var p=Source();var s=Read(p);Assert.AreEqual(5,((JArray)s.OriginalFormation["operators"]).Count);Assert.AreEqual(2,((JArray)s.OriginalLoadout["carriages"]).Count);s.OriginalFormation["operators"][0]["operatorId"]="changed";Assert.AreEqual("op0",(string)s.OriginalFormation["operators"][0]["operatorId"]);Assert.IsFalse(s.CanStart);Assert.Throws<InvalidOperationException>(()=>s.RequireOccupantBinding());}
 [TestCase("originAccount"),TestCase("originMissing"),TestCase("trainNull"),TestCase("trainEmpty"),TestCase("formationObject"),TestCase("rowObject"),TestCase("authority"),TestCase("slot")]
 public void RehashedMalformedSourceCannotCreateRuntimeAuthority(string kind){var p=Source();var d=p["originalDeparture"];switch(kind){case "originAccount":p["originalNativeOrigin"]["accountId"]="foreign";break;case "originMissing":((JObject)p["originalNativeOrigin"]).Remove("planHash");break;case "trainNull":d["loadout"]["trainId"]=JValue.CreateNull();d["ownedState"]["train"]["trainId"]=JValue.CreateNull();break;case "trainEmpty":d["loadout"]["trainId"]="";d["ownedState"]["train"]["trainId"]="";break;case "formationObject":d["formation"]=new JArray();break;case "rowObject":d["formation"]["operators"][0]=new JArray();break;case "authority":p["canStart"]=true;break;case "slot":d["formation"]["operators"][1]["slot"]=0;break;}Assert.Throws<ArgumentException>(()=>Read(p));}
 [Test] public void NativeContextCannotBeRunIdentity(){var p=Source();p["nativeContextId"]=p["runId"].DeepClone();Assert.Throws<ArgumentException>(()=>Read(p));}
 static IEnumerator Wait(Task t){var deadline=DateTime.UtcNow.AddSeconds(90);while(!t.IsCompleted){Assert.Less(DateTime.UtcNow,deadline);yield return null;}}
 [UnityTest,Timeout(180000)] public IEnumerator RealOriginalDepartureReadAndUnchangedFreshFullBudgetSupport(){var file=Environment.GetEnvironmentVariable("LASTRAIL_RESULT_CONNECTION");if(string.IsNullOrEmpty(file))Assert.Ignore("Explicit disposable LOCAL GAME/SQL source required");var connection=JObject.Parse(File.ReadAllText(file));var fresh=JObject.Parse(File.ReadAllText(Qa+"fresh-whole-v2-export.json"));var body=(JObject)fresh["originalRequestEnvelope"];var token=new GameApiAccessToken((string)connection["token"]);using(var adapter=new UnityWebRequestRunApiHttpAdapter((string)connection["origin"],30)){var raw=new GameApiAuthenticatedHttpTransport(new UnityWebRequestRunApiHttpTransport(adapter));var sourceClient=new BDepartureRuntimeInputClient(raw);var absent=sourceClient.ReadAsync("a",(string)connection["runId"],token);yield return Wait(absent);var absentError=absent.Exception.GetBaseException() as BResultReportHttpException;Assert.AreEqual(409,absentError.StatusCode);Assert.AreEqual("combat_b_departure_selection_unavailable",absentError.ErrorCode);
 var departureToken=new GameApiAccessToken((string)connection["departureToken"]);var read=sourceClient.ReadAsync("a",(string)connection["departureRunId"],departureToken);yield return Wait(read);var source=read.GetAwaiter().GetResult();var match=sourceClient.ReadAsync("a",(string)connection["departureRunId"],departureToken,source.PacketHash);yield return Wait(match);Assert.IsTrue(JToken.DeepEquals(source.Capture(),match.GetAwaiter().GetResult().Capture()));Assert.IsFalse(source.CanStart);var packet=(JObject)fresh["sourceBundle"];var bundle=BNativeNodeSourceSnapshot.Read(packet.ToString(),(string)packet["packetHash"],"a",(string)connection["runId"]);Assert.Throws<ArgumentException>(()=>source.RequireSameDeparture(bundle.Route));
 var stale=sourceClient.ReadAsync("a",(string)connection["departureRunId"],departureToken,new string('0',64));yield return Wait(stale);Assert.AreEqual(409,((BResultReportHttpException)stale.Exception.GetBaseException()).StatusCode);
 var wire=new RunApiHttpRequest("POST","/v1/runs/"+(string)connection["runId"]+"/b-result-reports",body.ToString(Newtonsoft.Json.Formatting.None),new[]{new RunApiHttpHeader("Content-Type","application/json"),new RunApiHttpHeader("X-B-Result-Version",BResultReportRequest.V2Version),new RunApiHttpHeader("Idempotency-Key",(string)body["requestId"])});var send=raw.SendAsync(wire,token);yield return Wait(send);var response=send.GetAwaiter().GetResult();Assert.AreEqual(200,response.Response.StatusCode);File.WriteAllText(Qa+"actual-http-v2-current-budget-and-departure.json",new JObject{["input"]="UNCHANGED_FRESH_WHOLE_V2_EXPORT",["fullUtf8Bytes"]=fresh["fullUtf8Bytes"].DeepClone(),["wholeNativeHash"]=fresh["wholeNativeHash"].DeepClone(),["status"]=200,["errorCode"]=RunApiErrorJsonAdapter.OptionalString(response.Response.BodyJson,"errorCode"),["sameRunDepartureStatus"]=409,["sameRunDepartureError"]=absentError.ErrorCode,["originalDepartureInput"]=source.Capture(),["departureSourceSeparateRun"]=true,["sameRunBindingRejected"]=true,["ifMatchRecovery"]=true,["staleStatus"]=409,["reportStored"]=true,["retryReceiptGetNotReached"]=true,["operatingStart"]=false}.ToString());}}
}}
